    <cds-slider
        [label]="'Budget-Rahmen'"
        [area]="'co'"
        [min]="10000"
        [max]="100000"
        [step]="5000"
        [value]="50000"
        [unit]="' €'"
        [tickCount]="5"
        [minTickSpacing]="56"
        [helper]="'Schritte: 5.000 €'"
        [disabled]="false"
        [sliderId]="'demo-slider'"
        (disabledChange)="disabledChange($event)"
        (valueChange)="valueChange($event)"
    />`,
})
export class DemoComponent {
  disabledChange(event: unknown) {}
  valueChange(event: unknown) {}
}

