import { Component } from '@angular/core';
import { SliderComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [SliderComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-slider
            label="Budget-Rahmen"
            sliderId="form-slider"
            [formControl]="ctrl">
        </cds-slider>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Wert:
            <strong>{{ ctrl.value }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {}
